 pub fn from(s:[u64;8],count:usize)->EbyKDot{EbyKDot{c0:canonical::Dot::NGY_from([s[0],s[1],s[2],s[3]]),c1:canonical::Dot::NGY_from([s[4],s[5],s[6],s[7]]),count}}
